# ── Section 1
S1_TITLE = 'What Sustains Performance'
S1_HERO = 'Performance Gravity, the Three Lines of Sight that show it, and the four KISS decisions that hold performance against it.'
S1_LO = ['Recognise the force that pulls achieved results back towards average.',
         'Identify the leadership decisions that hold performance against that pull.']
S1_GUIDE = [
 'Open with the question of the unit: once a result is achieved, what holds it? Teach 1.1 and 1.2 first, then return to the room with the opening question in the Key Facilitation Questions.',
 'In 1.2, connect each line to the result it reads: the Key Result for the strategic line, the ESRG scan for the operational line and the Health Thermometer for the behavioural line. Then show how WARD filters all three.',
 'In 1.3, define each KISS decision clearly. Section 2 explains why each one counters a form of drift, so keep 1.3 to what each decision is.',
]
P11 = [
 'Achieving a result and holding it are two separate leadership tasks. The strategy, the contributions and the performance system built across this programme produce results. Once achieved, those results come under a steady pull back towards the organisation’s historical average. This pull is <strong>Performance Gravity</strong>.',
 'Performance Gravity works quietly. Results often remain acceptable for several cycles while the conditions and behaviours that produced them weaken underneath. By the time the decline shows in the result, the cost of correcting it is far higher than the cost of noticing it early.',
 'Sustaining performance is the leadership discipline of seeing that pull early and responding to it every cycle.',
]
P12A = 'Performance Gravity shows first as drift on one of three lines of sight. Sustaining performance means keeping all three in view, every quarter, on the enterprise Key Result and the contributions in your S2R® Contribution Map™. Each line is read from a result your leadership team already produces.'
LINES = [
 ('Strategic', 'Is the Key Result still moving towards its Success in Practice?', 'The Key Result against its WARD waypoint (Unit 6)'),
 ('Operational', 'Are the organisational conditions still enabling the people’s tasks?', 'The ESRG scan: Operational Readiness, Operational Flow, Delivery Capacity and Decision Responsiveness (Unit 10)'),
 ('Behavioural', 'Are people still delivering the agreed behaviours?', 'The Organisational Health Thermometer: the functional health score and the five traits (Unit 11)'),
]
P12B = 'WARD, set for your enterprise Key Result in Unit 6, filters all three lines. Each line has a level it must hold (the waypoint), a point at which it raises a red flag (the alert), a recovery and a Decider.'
WARD_GRID = [
 ('W · Waypoint', 'The Key Result level set for this quarter', 'Each capability at Aligned (4.0–5.0)', 'Functional health at Healthy &amp; Thriving (80–100)'),
 ('A · Alert', 'More than the agreed margin below the waypoint', 'A capability below 3.0 (Significant or Critical constraint)', 'Functional health below 60 (Caution Zone or Unhealthy)'),
 ('R · Recovery', 'Recovery for individuals and for the organisational conditions', 'The owner of the condition restores it', 'The accountable executive restores the weakest traits'),
 ('D · Decider', 'The executive who decides on the recovery and sees it through', 'The same Decider', 'The same Decider'),
]
P12C = 'The operational and behavioural waypoints and alerts use the score bands already taught with the ESRG scan and the Health Thermometer. Drift usually raises an alert on the operational or behavioural line before the Key Result misses its waypoint. A leadership team that reads only the waypoint of the Key Result sees Performance Gravity last.'
R12_Q = 'Which of the three lines of sight does your leadership team read least, and what has that cost your organisation?'
P13 = 'At the close of every quarter, the leadership team makes four decisions about the practices, routines, behaviours and conditions behind its results.'
KISS = [
 ('K', 'Keep', 'Identify, name and protect the practices, routines, behaviours and conditions that are producing reliable results. Effective practices depend on leadership attention; when that attention moves elsewhere, they weaken without notice. Keep makes the implicit explicit: what is producing this result, and what must stay in place for it to continue?'),
 ('I', 'Improve', 'Recognise what was working well and is beginning to work less well, and recalibrate it while the gap is still a signal. Practices that were excellent six months ago may be merely adequate today. Improve corrects them before the gap shows in the result.'),
 ('S', 'Stop', 'Eliminate practices, meetings, processes, reports and approval layers that consume energy without producing commensurate value. Stop is the hardest decision, because every practice has a sponsor and people whose interests it serves.'),
 ('S', 'Start', 'Introduce what the organisation is not yet capable of and will need for the next level of performance. Start invests in future capability while current results make that investment possible.'),
]

